        '18326',
        'Check Aml watchlist checker screen',
        'Check Aml watchlist checker screen',
        'Based on our web session kindly find below the status:      • Issue Reported by the customer: Check AML watchlist checker screen .    • Status: Solved.    • Problem description: AML watchlist checker screen didn’t work because the screening tool services was not working.    • Action Taken—recommended solution: Based on our web session, the issue was resolved after turning on the services of the screening tool,     Please be informed that if the tool was not working the AML watchlist checker screen won’t return any of the searched names,     Here’s how you can turn on the screening tool if the server was restarted by your side:     • Go to this path: C:\Program Files (x86)\Pioneers Information Technology\SimilarityV3\January_Release  • Right Click on the AML_Screening.exe and run it as administrator         • An CMD screen will appear please do not close it so the AML Watchlist Checker screen keep searching for the names         • Then the screen will search without any problem,    Kindly check from your side and confirm to close this ticket.      Best Regards,',
