(
        '18402',
        'Upgrade SAP BO',
        'Dear Mr. Raed,  I hope this email finds you well.    Following our phone conversation, I am writing to request an upgrade of our current MIS solution from version 4.2 to version 4.3.    Could you kindly provide us with the necessary steps to proceed with this upgrade?    We would greatly appreciate your assistance in facilitating this process at your earliest convenience.    Thank you for your support, and we look forward to your response.',
        'Dear Mr. Mohammad    Kindly find below new application specs    Hardware Software  Sections Minimum requirements   CPU Minimum requirement 4 CPU (dual Core) and  preferable CPU (Quad core) Microsoft Windows Server 2019  Installed memory (RAM) Minimum requirement (32 GB) preferable (64 GB)   Hard Disk drive Space for database Hard Disk: 750 GB dedicated SSD hard drive divided into C: and D: 375 GB each       Best regards,  R M Raed Mansour  Product Support - Team Leader  Mobile: +962 79 8548068  Phone: +962 6 5805030 | Ext. 1058                                     From: Mohamed Chamakh <mohamed.chamakh@tib.com.tn>   Sent: Thursday, March 13, 2025 2:08 PM  To: Raed Mansour <raed.mansour@pio-tech.com>  Cc: Pio-Tech Support <Support@pio-tech.com>; Fehmi Benamar <fehmi.benamar@tib.com.tn>; Anouar Ouledali <anouar.ouledali@tib.com.tn>; mohamed mbarek <mohamed.mbarek@tib.com.tn>  Subject: RE: Notification for New Ticket 18402 - TIB-BOrenew-07-24 - Upgrade SAP BO    Dear Raed,     Thank you for your response.  Kindly send us the new hardware requirements.   Please note that we are currently using Oracle 19c.     Best regards.  Mohamed. CHAMAKH.     De : Raed Mansour [mailto:raed.mansour@pio-tech.com]   Envoyé : jeudi 13 mars 2025 11:11  À : Mohamed Chamakh <mohamed.chamakh@tib.com.tn>  Cc : Pio-Tech Support <Support@pio-tech.com>; Fehmi Benamar <fehmi.benamar@tib.com.tn>; Anouar Ouledali <anouar.ouledali@tib.com.tn>  Objet : Notification for New Ticket 18402 - TIB-BOrenew-07-24 - Upgrade SAP BO     ------------------------------------------------------------------------------------   This message originates from outside the bank. Please be   extra vigilant before you click on a link, open attachments or reply.   ------------------------------------------------------------------------------------   Dear Mohammad      Reference to our phone call kindly note upgrading SAP BO to the latest BO version which is SAP BO 4.3 sap4 patch 11 has some prerequisite as below :     - The upgrade must be applied on a new hardware since the SAP BO Objects will be migrated.  - SAP BO 4.3 SP4 depend on AL32UTF8 character set so we need to create new DB with AL32UTF8 character set to create new schema/repository.  - SAP BO 4.3 is not compatible with oracle 11g so we need to make sure the repository/schema DB version is oracle 19c.     So if above prerequisite can be achieved we can proceed installing SAP BO 4.3 sp4 patch 11.     Kindly check from your side and advise.',
