        'Dears,    Based on my web session and tracing the issues please consider the following:    Watchlists :  The lists currently in use are as follows in the column CAN_UPDATE :    PIO_WATCHLIST_TYPES Table  TYPE_ID DESCRIPTION CAN_UPDATE  1 OFAC (SDN) 1  2 OFAC (Non-SDN) 1  4 UN 1  16 PEPs 1  Data do not appear in the screen :  o I conducted random searches in the database tables and verified that names from the UN, OFAC (SDN), OFAC (Non-SDN), and PEP lists appear in the AML Watchlist Checker.  o The following tables should be used for verification of the names you search for:   ? PIO_WATCHLIST_SDNENTRY_AKA  ? PIO_WATCHLIST_SDNENTRY  ? PIO_WATCHLIST_SDNENTRY_HIS  ? PIO_WATCHLIST_SDNENTRY_AKA_HIS  PEP’s names:  o Based on my review of the names discussed in our meeting, the names in the PEP list do not appear in the tables mentioned above perhaps due to changes in the list from the provider side.    Summary :     The system is functioning correctly across all screens, and the data in the database appears as expected on the screens.     Please let me know if any additional checks or clarifications are required.    Best Regards,',
