        '18476',
        'Issue with Closing Word Check Alerts',
        'Issue with Closing Word Check Alerts',
        'Dear Esraa,    Based on our web session and further investigation, it appears that the alert may have been opened in multiple browser windows. In the case mentioned below, a senior-level user first performed the "Back" action in one browser and then make the "Final Status" action in a second browser ,as shown in the attached picture. This may have caused the issue.    Please check the "Workflow Information" tab and ensure that when a user take action on an alert, it is opened in only one browser window.',
