(
        '18495',
        'SAP Data Services Job Failed: FILL_ALL_TYPE',
        'Dears    - ETL daily fill job “FILL_ALL_TYPES” failed due to the below error.',
        'Based on our web session kindly find below the status:      • Issue Reported by the customer: SAP Data Services Job Failed: FILL_ALL_TYPE.    • Status: Solved.    • Problem description: ETL daily fill job “FILL_ALL_TYPES” failed due to lack of storage on the DB server.                   • Action Taken—recommended solution: Based on our web session, Kindly note that the issue was resolved by extending the DB server size from your side ,reclaiming about (1TB) from the ODS storage size & re-executing the “FILL_ALL_TYPES” ETL job from where it stopped, Noting that the Job has been completed successfully for the date “25/03/2025”,noting that today’s fill was running successfully on its scheduled time without any issues. Kindly check & confirm.   Kindly check from your side and confirm in order to close this ticket.',
        '2025-03-26T00:00:00.000Z'::timestamptz,
