        '18496',
        'Outward Messages are Stuck in LIVE system',
        'Dear Team, Some of the messages are stuck in AML system and keeps repeating . We found the below response of AML system sending back to CBS   system . please urgently look into this issue as the payment is stuck .  2025-03-26 10:53:16,566 DEBUG [TokenWebServiceCaller.java:273]: PrepareAMLforCalling (step 8) : the calling done and start to read the response (code/messgae) ..   2025-03-26 10:53:27,073 DEBUG [TokenWebServiceCaller.java:275]: getResponseCode = [500]  2025-03-26 10:53:27,073 DEBUG [TokenWebServiceCaller.java:276]: getResponseMessage = [Internal Server Error]  2025-03-26 10:53:27,073 DEBUG [TokenWebServiceCaller.java:293]: PrepareTokenForCalling (step 9) : response is = "Something Went Wrong"  2025-03-26 10:53:27,073 DEBUG [TokenWebServiceCaller.java:354]: PrepareAMLforCalling (step 9.2) : the calling was failed .. 500  2025-03-26 10:53:27,073 INFO [ScreeningReqHandler.java:193]: getAMLRequest (step 12-error) : invalid response from AML webservice after calling',
        'Issue has been solved, the root cause as per Mohammad Al- Shaikh feedback to the bank team:    Dears   We received a support ticket from you indicating that there is an issue with payment screening.   ? We communicated with your team and completed the following.   ? The database passwords have not expired.  ? The screening program functions well.   ? We reviewed the fast log and found no outstanding transactions.  ? Upon reviewing the screening log, we discovered an issue relating to the "Pooled connection request" and notified Nusrat.  And we made no changes to the application, and Mr. Nasrat informed us that the system is running well.',
