        '18703',
        'Upload manual list',
        'Upload manual list',
        'Based on our web session kindly find below the status:      • Issue Reported by the customer: Upload manual list.    • Status: Solved.    • Problem description: Uploading Manual List through the watchlist loader tool after modifying the data inside the template and giving notes to the compliance team for the other side .    • Action Taken—recommended solution: Based on our web session, the issue was resolved as follows:     1- Uploading the list through the tool in this file path:    C:\Program Files (x86)\Pioneers Information Technology\WatchList Loader 1.0.27            2- Running the procedure BI_DWH.FILL_PIO_WATCHLIST_SDNNTRY_AKA    From the Toad for Oracle     Schema browser-procedures- *name of the procedure*          3- Re Running the services of the AML Screening service as Administrator in this file path:    C:\Program Files (x86)\Pioneers Information Technology\SimilarityV3\January_Release         After these steps you can refresh the page in the browser and search for the requested name by putting his first name and last name and you can find it as shown in the attached file ,    Kindly check from your side and confirm to close this ticket.    And please if you have any question regarding the process do not hesitate to contact us,',
