(
        '18738',
        'Issue on similarity',
        'Internal blacklist isn’t working today , as illustrated many times before it’s a critical issue , please to connect and solve the needed.',
        'Issue Reported    Issue on similarity that does not allow the team to search for the names    Problem description    After the investigation we found poor performance in the DB server that caused major delay on the process, and the similarity tool is not functioning properly.    Root cause of the issue    AKA table, which contains approximately 200 ++ million names that is related to Dow-Jones list , and the DB server needs some tunings, both reasons are impacting the fuzzy matching processing.    Action Taken    • Pio-Tech DBA team did Index rebuild and check the partitioning to avoid making full scan in 2024 and 2025, indexes impacted table (PIO_WATCHLIST_SDNNTRY_AKA) and (PIO_WATCHLIST_SDNNTRY)    • Memory enhancement on PGA to 15 GB-RAM SGA to 8GB-RAM    • A full review of the fuzzy matching algorithm used in the similarity tool was conducted to discover the reason behind the huge number of records in AKA table    • Implement workaround on the AKA table to make sure the current number of records are on the normal range without any duplication    Note: We will keep this site under monitoring for two days',
        '2025-04-22T00:00:00.000Z'::timestamptz,
        '2025-04-22T00:00:00.000Z'::timestamptz,
