(
        '18757',
        'Duplicate offline screening alerts',
        'Duplicate offline screening alerts',
        'Based on our web session kindly find below the status:      • Issue Reported by the customer: Duplicate offline screening alerts .    • Status: Solved.    • Problem description: The system was generating duplicate alerts due to reading data from screening lists that were not activated. These inactive lists were still being processed because their delta flag had not been correctly updated, causing the screening engine to include them in its checks and that is the root cause of the problem,    • Action Taken—recommended solution: Based on our web session, the issue after we noticing that the delta flag for the non-activated lists had not been properly set. This allowed the system to continue referencing them, which led to the duplicate alerts,  We updated the delta flags for all inactive lists accordingly, which resolved the issue by ensuring the screening system now only reads from properly activated lists,     Kindly check from your side and confirm to close this ticket.',
        '2025-04-24T00:00:00.000Z'::timestamptz,
        '2025-05-06T00:00:00.000Z'::timestamptz,
