(
        '18760',
        'Names don''t appear on interface',
        'Dears,     I urgently need your assistance to reevaluate the system configuration, as the internal blacklist is not functioning correctly.    This issue is impacting our business and exposing us to regulatory risks. I will send a meeting link shortly. Please join the meeting so we can address and resolve this issue immediately.    Thank you for your prompt attention to this matter.',
        'Dears,    • Issue Reported by the customer: Names don’t appear on the interface .    • Status: Solved.    • Problem description: Names don''t appear on interface because of the engine,    • Action Taken—recommended solution: During our web session, we traced the issue to the engine of the AKA system and the configuration of the similarity tool. We discovered that the engine should populate a temporary table, which the similarity tool reads from. However, the newly updated names were not being reflected due to misalignment in this process.    We updated the engine configuration to ensure it populates the temporary table with new names, and we also adjusted the similarity tool to read from this table accordingly. After these changes, the names started appearing on the interface as expected.     Note : We will continue to monitor the system for up to 3 days to ensure the temporary table is being filled correctly and consistently.     Kindly check from your side and confirm to close this ticket',
        '2025-04-24T00:00:00.000Z'::timestamptz,
        '2025-04-24T00:00:00.000Z'::timestamptz,
