(
        '18789',
        'Outward Messages are Stuck in Test system',
        'Dear Piotech team    We have issue in AML system , MT103 and MT202 not appearing in AML portal , but I can see there are multiple MTs in Pio_api_monitor,     These are urgent payment and needs to be released today itself. Need your urgent support.    Thanks',
        'Dears    We investigated the MT103 message (Reference 490) and discovered the following.    1. Because ethe similarity was run twice, our engine stopped producing the message.  2. Since the status is null, it indicates that the process is still paused.  3. In a typical scenario, we would have sent a suspicious or not suspicious message to the core banking system, but we didn''t.  4. We must manually execute our swift engine for all stop messages (status = -1) if the transfers were stopped.    To be sure, send us the response that received to the core banking system.      Regards',
