(
        '18732',
        'Diff between AML basket and reports',
        'Dear Braa,    Kindly note that attached report for alerts under batch screening status false positive while it is under open alert report.',
        'Dears,    Based on our web session, please be informed that the issue with the AML Open Alerts report has been resolved after rechecking the engine responsible for reflecting alerts from the database to the report, we have confirmed that the number of alerts displayed in the report now matches the actual alert count in the database for the specified period: “01-Jan-2024 to 31-Dec-2024” as shown in the pictures below.              Additionally, please note that some alerts may appear to be locked by other users. This occurs at your site due to multiple users being assigned to the same branch under different groups. This configuration can cause discrepancies between the number of alerts shown in the report and the number displayed in the job basket. To ensure consistency and accuracy in alert counts per user, we recommend assigning each branch to only one group — which is the standard practice. This will allow you to correctly monitor the number of open alerts for each selected user.    Please check from you side and confirm so we can proceed with closing the ticket below.',
