        '18839',
        'Solving Vulnerability',
        'Solving Vulnerability',
        'Dear @Zeater O,    It might be on the OS level not on the application level, that’s why the bank security team should update on it. More details and checkup is requested to understand the issue, as I mentioned previously this is generic note. The below are just samples.    Examples of CWE-200 Vulnerabilities:  1. Detailed Error Messages: A web server showing database errors with table names, credentials, or query logic.  2. Verbose HTTP Headers: Response headers revealing the software version which could aid attackers.  3. Unprotected API Endpoints: APIs returning sensitive data (e.g., usernames, email addresses, or tokens) without authentication.  4. Directory Listings Enabled: A web server that allows users to browse files in a directory due to lack of proper configuration.      Thank you,    M A Mohammad Ammoura  Head of Product Support Unit  Mobile: +962 77 2963400  Phone: +962 6 5805030 | Ext. 1057                                     From: Zeater O <Zeater.O@ahlibank.om>   Sent: Tuesday, May 6, 2025 11:37 AM  To: Mohammad Ammoura <mohammad.ammoura@pio-tech.com>  Cc: Pio-Tech Support <Support@pio-tech.com>; ITE Support <ITESupport@ahlibank.om>; Shadi A. Alhourani <Shadi.AlHourani@ahlibank.om>  Subject: RE: Portal Ticket, Solving Vulnerability , Al-Ahli Bank (ABO)    Dear Mohammed ,      The point on Pio-Tech application , Regarding CVE number its mentioned in the excel : CWE-200      Regards     From: Mohammad Ammoura <mohammad.ammoura@pio-tech.com>   Sent: Tuesday, May 6, 2025 12:28 PM  To: Shadi A. Alhourani <Shadi.AlHourani@ahlibank.om>; ITE Support <ITESupport@ahlibank.om>  Cc: Pio-Tech Support <Support@pio-tech.com>  Subject: RE: Portal Ticket, Solving Vulnerability , Al-Ahli Bank (ABO)        ________________________________________  Security Notice: The attachments in this email were secured by a Check Point SandBlast.  The original attachments were not modified.  ________________________________________',
