        '18867',
        'ETL service issue',
        'IIAB_FILL_ALL_TYPES Has Been Finished Unsuccessfully,Error Message: ODBC data source <DWH-SQL-CLUSTER\IIABBI> error message for operation <SQLExecute>: <[Microsoft][ODBC Driver 17 for SQL Server][SQL Server]Backup, file manipul...',
        'Dear Bilal,  Good evening, I hope this email finds you well.    The ETL fails at the beginning of the ETL process at the “shrink databases” script. keep in mind that this script runs daily and has been part of the ETL workflow since day one of the project.    As I mentioned in my previous email, this type of failure typically occurs when SQL Server encounters a conflict between simultaneous operations on the database. These conflicts usually involve backups, file manipulations, or encryption changes. For example:    • You cannot run ALTER DATABASE while a backup is running.    • You cannot encrypt or decrypt the database while adding or removing files.    Common scenarios that might cause such conflicts include:    • A backup is running (manual, scheduled, or automated)    • A restore operation is in progress    • A Transparent Data Encryption (TDE) change is occurring    • Attempting to add or remove a data/log file simultaneously    Best Regards,',
        '2025-05-10T00:00:00.000Z'::timestamptz,
