(
        '18846',
        'RBA session',
        'RBA session',
        'Dears @Rawan Qaisi / @Samer Othman    Based on our session, I have provided you with an overview of the following topics related to the RPA Engine.  Please feel free to share any notes or questions if anything is unclear. For more details, please find the RPA Engine documentation in both Arabic and English attached.    o Risk Categories: to classify or re-classify customers; these categories are used in the risk assessment reports where required.  o Parameter Category: defines the risk assessment parameter categories users can use on the risk matrix page  o Overrule Parameters: to define the system parameters that will be used as overrule parameters.   o Risk Parameter Weight: to add weight to the risk parameter, and each is influenced by various factors; these factors are defined in the risk matrix page and are assigned a weight so that the total weight of all the one parameter factors together equals 100.   o Customer Score: to view the customer classification and classification details within a report, with the ability to export this report in PDF format.  o Risk Reports: Viewing various RPA reports',
        '2025-05-11T00:00:00.000Z'::timestamptz,
        '2025-05-11T00:00:00.000Z'::timestamptz,
